def __len__(self):
    if self.iterable is None:
        return self.total
    elif hasattr(self.iterable, "shape"):
        return self.iterable.shape[0]
    elif hasattr(self.iterable, "__len__"):
        return len(self.iterable)
    else:
        return getattr(self, "total", 0)  # Return 0 as a fallback for non-measurable iterables

def __bool__(self):
    # Return True if total is set (indicating there is work expected) or if len is greater than 0
    return self.total > 0 if self.total is not None else bool(self.iterable)
