def __len__(self):
    if self.total is not None:
        return self.total
    if self.iterable is None:
        return None
    if hasattr(self.iterable, "shape"):
        return self.iterable.shape[0]
    if hasattr(self.iterable, "__len__"):
        return len(self.iterable)
    return None

def __bool__(self):
    # Return True if total is specified or if the iterable is non-empty
    if self.total is not None:
        return self.total > 0
    if self.iterable is None:
        return False
    # Check if the iterable has length and is non-empty
    if hasattr(self.iterable, "__len__"):
        return len(self.iterable) > 0
    # If it's an iterator, see if it can provide a next element
    try:
        next(iter(self.iterable))
        return True
    except (StopIteration, TypeError):
        return False
```

